import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"南丰县：智慧养殖赋能家禽产业提质增效","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"南丰县：智慧养殖赋能家禽产业提质增效","date":"2026-08-25T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260824_6486917.htm","summary":"近年来,江西抚州南丰县立足本地家禽养殖产业基础,以数字化转型为抓手,引导规模化养殖场升级无人化智能养殖系统,通过科技手段降本增效,推动传统养殖向智慧养殖提档升级,为乡村产业振兴注入强劲科技动力。\\n走进太和镇抚州屹立生态禽业发展有限公司养殖场,密闭式标准化鸡舍内几乎看不到饲养人员的身影。自动饲喂系统沿轨道精准定量投喂,智能巡检设备不间断监测鸡群状态,能识别病弱个体并同步预警。...\\n","contentHash":"e74fa5721ba366e26b61bcc73b9118a3","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-25-南丰县-智慧养殖赋能家禽产业提质增效.md","filePath":"news/2026-08-25-南丰县-智慧养殖赋能家禽产业提质增效.md"}'),n={name:"news/2026-08-25-南丰县-智慧养殖赋能家禽产业提质增效.md"};function s(o,e,l,p,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="南丰县-智慧养殖赋能家禽产业提质增效" tabindex="-1">南丰县：智慧养殖赋能家禽产业提质增效 <a class="header-anchor" href="#南丰县-智慧养殖赋能家禽产业提质增效" aria-label="Permalink to &quot;南丰县：智慧养殖赋能家禽产业提质增效&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260824_6486917.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-08-25 摘要: 近年来,江西抚州南丰县立足本地家禽养殖产业基础,以数字化转型为抓手,引导规模化养殖场升级无人化智能养殖系统,通过科技手段降本增效,推动传统养殖向智慧养殖提档升级,为乡村产业振兴注入强劲科技动力。 走进太和镇抚州屹立生态禽业发展有限公司养殖场,密闭式标准化鸡舍内几乎看不到饲养人员的身影。自动饲喂系统沿轨道精准定量投喂,智能巡检设备不间断监测鸡群状态,能识别病弱个体并同步预警。...</p></blockquote><p>走进太和镇抚州屹立生态禽业发展有限公司养殖场,密闭式标准化鸡舍内几乎看不到饲养人员的身影。自动饲喂系统沿轨道精准定量投喂,智能巡检设备不间断监测鸡群状态,能识别病弱个体并同步预警。从饲喂、环境调控到清粪、集蛋,养殖全流程基本实现无人化作业,管理人员通过中控平台即可远程管控全场运行。</p><p>目前,该养殖场存栏蛋鸡11万余羽,仅需2至3名工作人员即可完成日常运维。与传统养殖相比,人工成本降低50%,产蛋率稳定提高80%,疫病防控精准度显著增强。</p><p>“过去全靠人工喂料、巡栏,劳动强度大,还容易有疏漏。现在换上无人化设备,手机上就能实时掌握鸡舍情况,省了人力、提了效益,鸡蛋品质也更稳定。”养殖场负责人胡小亮表示,下一步计划扩大养殖规模,继续依靠科技提升效益。</p><p>无人化养殖经验正逐步复制推广。在万羽养殖专业合作社智能肉鸽养殖基地项目现场,标准化鸽舍主体施工加快推进。项目对标智慧养殖标准,配套自动饲喂、智能环境调控及种蛋自动收集系统,投产后核心环节基本实现无人化作业。满产后可存栏种鸽十余万对,进一步拓宽村集体增收渠道。“我们从规划阶段就引入智能化养殖方案,既能降低人工成本,也能稳定养殖环境、提升肉鸽品质。”合作社负责人马呈根表示,项目预计今年底可建成投产。</p><p>从蛋鸡养殖智能化落地到肉鸽养殖智慧化布局,南丰县正逐步构建多点支撑的智慧养殖产业体系。数字化技术与传统养殖业深度融合,持续推动家禽产业提质增效,有效带动村集体增收、农民致富,为县域农业现代化和乡村产业振兴筑牢科技根基。(黄恒宇)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260824_6486917.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',8)])])}const h=t(n,[["render",s]]);export{f as __pageData,h as default};
